def decode_bus(data):
 if data[1024:1032]!=b'NXLPATH1':return None
 path_capacity=struct.unpack_from('<I',data,1040)[0]
 if path_capacity==11:return None
 if path_capacity!=3:raise ValueError('Unsupported DMA/path layout')
 ring=data[2048:4096]
 if ring[:8]==bytes(8):raise ValueError('Missing DMA snapshot extension')
 if ring[:8]!=b'NXLBUS1\0':raise ValueError('Unknown DMA snapshot extension')
 magic,schema,size,capacity,total,mask,reserved=struct.unpack_from('<8s6I',ring)
 if (schema,size,capacity,reserved)!=(1,624,3,0) or mask&~7:raise ValueError('Invalid DMA snapshot metadata')
 rows=[]
 for phase in range(3):
  if not mask&(1<<phase):continue
  raw=ring[32+size*phase:32+size*(phase+1)];w=struct.unpack('<156I',raw)
  if w[-1]!=(fnv(raw[:-4])^0x6d28a791) or w[0]>=total or w[3]!=phase or w[2] not in (1,2,3,4):raise ValueError('DMA snapshot integrity failed')
  if w[13]&~255 or w[18]&~255:raise ValueError('Invalid DMA validity mask')
  for i in range(5):
   if w[14+i]&~w[9+i]:raise ValueError('Changed unavailable DMA word')
  fields=[]
  for i,meta in enumerate(REGISTERS):
   valid=bool(w[9+i//32]&(1<<(i%32)));changed=bool(w[14+i//32]&(1<<(i%32)))
   fields.append(dict(**meta,value=hex(w[19+i])if valid else None,changed_between_reads=changed))
  groups=[]
  for group in GROUPS:
   values=[w[19+group['first']+i] for i in range(group['count'])]
   available=all(fields[group['first']+i]['value']is not None for i in range(group['count']))
   changed=any(fields[group['first']+i]['changed_between_reads']for i in range(group['count']))
   item=dict(kind=group['kind'],configuration_bank=group['bank'],port=group['port'],all_available=available,changed_between_reads=changed)
   if available:
    item.update(plane0_address=hex(values[0]),plane1_address=hex(values[1]),plane_address_high_bytes=[hex(values[j]>>24)for j in [0,1]])
    if group['kind']=='IPC_DMA':item.update(stride_bytes=values[2]&0x7ffff,bit_depth=8+2*((values[3]>>8)&7),threshold_candidate_bits_9_0=values[4]&1023,size_low16=values[5]&65535,size_high16=values[5]>>16)
    else:item.update(stride_bytes=(values[2]>>12)&0x7ffff,bit_depth=8+2*((values[2]>>8)&7),control_candidate_bits_11_8=(values[4]>>8)&15,control_candidate_bits_23_16=(values[4]>>16)&255,control_candidate_bits_31_24=(values[4]>>24)&255)
   groups.append(item)
  rows.append(dict(sequence=w[0],elapsed_s=w[1]/1000,status=w[2],phase=['preview','recording','after_stop'][phase],driver_mode=hex(w[4]),scene=hex(w[5]),preset=hex(w[6]),frame_sequence_before=w[7],frame_sequence_after=w[8],crossed_frame=w[7]!=w[8],registers=fields,DMA_groups=groups))
 return dict(schema='NXL_BUS1',total_captured=total,records=rows,interpretation='Original IPC/EP configuration values only, at most every five seconds. Configuration banks are not physical DDR channels. Candidate fields have verified native input-to-register bit mapping but unverified burst/outstanding names. Each word is read twice; changed flags and before/after frame sequence expose races. This is not an atomic frame snapshot, bandwidth or stall counter.')
